// Expand onto the shared monthly axis: each month takes its calendar year's
// OEWS employment (the latest year carried forward to "now"), converted to
// active vacancies with that month's state openings rate.
// Month index → index into US_YEARS: the most recent published vintage at or
// before that month's calendar year, or -1 when the month predates the first
// vintage. Forward-filling this way means a gap year inherits the previous
// vintage and months after the last one carry it forward to "now".
const YEAR_SLOT: number[] = IVI_MONTHS.map((ym) => {
  const y = Number(ym.slice(0, 4));
  let slot = -1;
  for (let i = 0; i < US_YEARS.length; i++) if (US_YEARS[i] <= y) slot = i;
  return slot;
});

function expand(byCity: Record<string, number[]>): Record<string, number[]> {
  const out: Record<string, number[]> = {};
  for (const [city, emp] of Object.entries(byCity)) {
    const rate = US_STATE_RATE[US_CITY_STATE[city]] || [];
    out[city] = YEAR_SLOT.map((yi, i) => {
      if (yi < 0) return 0;
      const e = emp[yi] || 0;
      const r = (rate[i] || 0) / 100;
      if (e <= 0 || r <= 0 || r >= 1) return 0;
      return Math.round((e * r) / (1 - r));
    });
  }
  return out;
}

// Skill → metro → monthly vacancy history (aligned to IVI_MONTHS).
export const US_SERIES: Record<string, Record<string, number[]>> =
  Object.fromEntries(Object.entries(US_EMPLOYMENT).map(([s, e]) => [s, expand(e)]));

// Skill → latest-month metro vacancy count (current heat map).
export const US_SKILL_BY_CITY: Record<string, Record<string, number>> =
  Object.fromEntries(
    Object.entries(US_SERIES).map(([s, byCity]) => [
      s,
      Object.fromEntries(Object.entries(byCity).map(([c, arr]) => [c, arr[arr.length - 1]])),
    ]),
  );
